    start_row = 6 if white else 1

    for row in range(8):
        for col in range(8):
            piece = rows[row][col]
            if piece is None:
                continue
            if not ((piece.isupper() and white) or (piece.islower() and not white)):
                continue
            kind = piece.lower()
            if kind == "p":
                fwd = row + pawn_dir
                if 0 <= fwd < 8 and rows[fwd][col] is None:
                    moves.append(_sq(row, col) + _sq(fwd, col))
                    if row == start_row and rows[row + 2 * pawn_dir][col] is None:
