                    while 0 <= r2 < 8 and 0 <= c2 < 8:
                        target = rows[r2][c2]
                        if target is None:
                            moves.append(_sq(row, col) + _sq(r2, c2))
                        else:
                            if _is_enemy(target, white):
                                moves.append(_sq(row, col) + _sq(r2, c2))
