            moves.append("e8g8")
        if "q" in rights and _can_castle(rows, False, False):
            moves.append("e8c8")
    return moves


def _apply_move(fen: str, move: str) -> str:
    parts = fen.strip().split()
    rows = _rows(parts[0])
    fr, fc = _parse_sq(move[:2])
    tr, tc = _parse_sq(move[2:4])
