    parts[0] = _placement(rows)
    parts[1] = "b" if white else "w"
    if len(parts) > 2:
        parts[2] = "".join(r for r in "KQkq" if r in rights) or "-"
    if len(parts) > 3:
        parts[3] = str(halfmove)
    if len(parts) > 4:
        parts[4] = str(fullmove)
    return " ".join(parts)


def perft(fen: str, depth: int) -> int:
    if depth == 0:
        return 1
    count = 0
    for move in legal_moves(fen):
        count += perft(_apply_move(fen, move), depth - 1)
    return count

